public abstract class EsquemaDyC<P, R> {
    public abstract boolean esCasoBase(P problema);
    public abstract R solucionDirecta(P problema);
    public abstract P[] descomponer(P problema);
    public abstract R combinar(R[] solucionesParciales);

    public R resolver(P problema) {
        if (esCasoBase(problema)) {
            return solucionDirecta(problema);
        }
        P[] subproblemas = descomponer(problema);
        @SuppressWarnings("unchecked")
        R[] soluciones = (R[]) new Object[subproblemas.length];
        for (int i = 0; i < subproblemas.length; i++) {
            soluciones[i] = resolver(subproblemas[i]);
        }
        return combinar(soluciones);
    }
}

