public static long potenciaOptimizada(long a, int n) {
    if (n == 1) return a;
    if (n == 2) return a * a;
    long quad = potenciaOptimizada(a, n / 2);
    long res = quad * quad;
    if (n % 2 != 0) {
        res *= a;
    }
    return res;
}

public static int busquedaBinaria(VectorTDA<Integer> valores, int inicio, int fin, int valor) throws Exception {
    if (inicio > fin) {
        return -1;
    }
    int mitad = inicio + (fin - inicio) / 2;
    int elemento = valores.recuperarElemento(mitad);
    if (elemento == valor) {
        return mitad;
    } else if (valor < elemento) {
        return busquedaBinaria(valores, inicio, mitad - 1, valor);
    } else {
        return busquedaBinaria(valores, mitad + 1, fin, valor);
    }
}

public static void mergeSort(VectorTDA<Integer> valores, int inicio, int fin) throws Exception {
    if (inicio < fin) {
        int medio = inicio + (fin - inicio) / 2;
        mergeSort(valores, inicio, medio);
        mergeSort(valores, medio + 1, fin);
        merge(valores, inicio, medio, fin);
    }
}

private static void merge(VectorTDA<Integer> valores, int inicio, int medio, int fin) throws Exception {
    int n = fin - inicio + 1;
    int[] aux = new int[n];
    int i = inicio;
    int j = medio + 1;
    int k = 0;
    while (i <= medio && j <= fin) {
        if (valores.recuperarElemento(i) <= valores.recuperarElemento(j)) {
            aux[k++] = valores.recuperarElemento(i++);
        } else {
            aux[k++] = valores.recuperarElemento(j++);
        }
    }
    while (i <= medio) {
        aux[k++] = valores.recuperarElemento(i++);
    }
    while (j <= fin) {
        aux[k++] = valores.recuperarElemento(j++);
    }
    for (k = 0; k < n; k++) {
        valores.agregarElemento(inicio + k, aux[k]);
    }
}

public static void quickSort(VectorTDA<Integer> valores, int inicio, int fin) throws Exception {
    if (inicio < fin) {
        int p = particionar(valores, inicio, fin);
        quickSort(valores, inicio, p - 1);
        quickSort(valores, p + 1, fin);
    }
}

private static int particionar(VectorTDA<Integer> valores, int inicio, int fin) throws Exception {
    int pivote = valores.recuperarElemento(inicio);
    int i = inicio + 1;
    int j = fin;
    while (true) {
        while (i <= fin && valores.recuperarElemento(i) <= pivote) {
            i++;
        }
        while (j >= inicio && valores.recuperarElemento(j) > pivote) {
            j--;
        }
        if (i < j) {
            int aux = valores.recuperarElemento(i);
            valores.agregarElemento(i, valores.recuperarElemento(j));
            valores.agregarElemento(j, aux);
        } else {
            break;
        }
    }
    int aux = valores.recuperarElemento(inicio);
    valores.agregarElemento(inicio, valores.recuperarElemento(j));
    valores.agregarElemento(j, aux);
    return j;
}

