public static class Candidato {
    public boolean r;
    public int n;
    public int c;
    public int x;
    public Candidato(boolean r, int n, int c, int x) {
        this.r = r; this.n = n; this.c = c; this.x = x;
    }
}

public static Candidato pseudoM(int[] u, int i, int j) {
    if (i == j) return new Candidato(true, 1, 1, u[i]);
    int mid = i + (j - i) / 2;
    Candidato o1 = pseudoM(u, i, mid);
    Candidato o2 = pseudoM(u, mid + 1, j);
    int nTotal = o1.n + o2.n;
    if (!o1.r && !o2.r) return new Candidato(false, nTotal, 0, 0);
    if (o1.r && !o2.r) return new Candidato(true, nTotal, o1.c + o2.n / 2, o1.x);
    if (!o1.r && o2.r) return new Candidato(true, nTotal, o2.c + o1.n / 2, o2.x);
    if (o1.x == o2.x) return new Candidato(true, nTotal, o1.c + o2.c, o1.x);
    if (o1.c > o2.c) return new Candidato(true, nTotal, o1.c - o2.c, o1.x);
    if (o2.c > o1.c) return new Candidato(true, nTotal, o2.c - o1.c, o2.x);
    if (o1.n < o2.n) return new Candidato(true, nTotal, o1.c + o2.n / 2, o1.x);
    if (o2.n < o1.n) return new Candidato(true, nTotal, o2.c + o1.n / 2, o2.x);
    return new Candidato(false, nTotal, 0, 0);
}

public static Integer elementoMayoritaro(int[] u) {
    if (u == null || u.length == 0) return null;
    Candidato cand = pseudoM(u, 0, u.length - 1);
    if (!cand.r) return null;
    int cuenta = 0;
    for (int num : u) {
        if (num == cand.x) cuenta++;
    }
    return (cuenta > u.length / 2) ? cand.x : null;
}

public static void fixture(int[][] T, int first, int last) {
    if (first == last - 1) {
        T[first][0] = last + 1;
        T[last][0] = first + 1;
    } else {
        int mid = first + (last - first) / 2;
        fixture(T, first, mid);
        fixture(T, mid + 1, last);
        completarT(T, first, last);
    }
}

private static void completarT(int[][] T, int first, int last) {
    int len = (last - first + 1) / 2;
    int firstAdversary = first + len + 1;
    int secondAdversary = first + 1;
    int firstDay = len - 1;
    int lastDay = firstDay + len;
    for (int j = firstDay; j < lastDay; j++) {
        T[first][j] = firstAdversary++;
        T[first + len][j] = secondAdversary++;
    }
    for (int i = first + 1; i <= first + len - 1; i++) {
        for (int j = firstDay; j < lastDay; j++) {
            if (j == firstDay) {
                T[i][j] = T[i - 1][lastDay - 1];
                T[i + len][j] = T[i + len - 1][lastDay - 1];
            } else {
                T[i][j] = T[i - 1][j - 1];
                T[i + len][j] = T[i + len - 1][j - 1];
            }
        }
    }
}

public static int mpsDivideAndConquer(int[] A, int ini, int fin) {
    if (ini == fin) {
        return A[ini];
    }
    int mid = ini + (fin - ini) / 2;
    int maxIzq = mpsDivideAndConquer(A, ini, mid);
    int maxDer = mpsDivideAndConquer(A, mid + 1, fin);

    int suma = 0;
    int sumLMPS = Integer.MIN_VALUE;
    for (int i = mid; i >= ini; i--) {
        suma += A[i];
        if (suma > sumLMPS) sumLMPS = suma;
    }

    suma = 0;
    int sumRMPS = Integer.MIN_VALUE;
    for (int j = mid + 1; j <= fin; j++) {
        suma += A[j];
        if (suma > sumRMPS) sumRMPS = suma;
    }

    int maxCruce = sumLMPS + sumRMPS;
    return Math.max(Math.max(maxIzq, maxDer), maxCruce);
}

public static MatrizTDA<Integer> strassen(MatrizTDA<Integer> A, MatrizTDA<Integer> B, int ai, int aj, int bi, int bj, int n) throws Exception {
    if (n <= 2) {
        return producto2x2(A, B, ai, aj, bi, bj);
    }
    int k = n / 2;
    MatrizTDA<Integer> m1 = strassen(suma(A, A, ai, aj, ai + k, aj + k, k), suma(B, B, bi, bj, bi + k, bj + k, k), 0, 0, 0, 0, k);
    MatrizTDA<Integer> m2 = strassen(suma(A, A, ai + k, aj, ai + k, aj + k, k), B, 0, 0, bi, bj, k);
    MatrizTDA<Integer> m3 = strassen(A, resta(B, B, bi, bj + k, bi + k, bj + k, k), ai, aj, 0, 0, k);
    MatrizTDA<Integer> m4 = strassen(A, resta(B, B, bi + k, bj, bi, bj, k), ai + k, aj + k, 0, 0, k);
    MatrizTDA<Integer> m5 = strassen(suma(A, A, ai, aj, ai, aj + k, k), B, 0, 0, bi + k, bj + k, k);
    MatrizTDA<Integer> m6 = strassen(resta(A, A, ai + k, aj, ai, aj, k), suma(B, B, bi, bj, bi, bj + k, k), 0, 0, 0, 0, k);
    MatrizTDA<Integer> m7 = strassen(resta(A, A, ai, aj + k, ai + k, aj + k, k), suma(B, B, bi + k, bj, bi + k, bj + k, k), 0, 0, 0, 0, k);

    MatrizTDA<Integer> C = new Matriz<Integer>();
    C.inicializarMatriz(n);
    for (int i = 0; i < k; i++) {
        for (int j = 0; j < k; j++) {
            C.setearValor(i, j, m1.obtenerValor(i, j) + m4.obtenerValor(i, j) - m5.obtenerValor(i, j) + m7.obtenerValor(i, j));
            C.setearValor(i, j + k, m3.obtenerValor(i, j) + m5.obtenerValor(i, j));
            C.setearValor(i + k, j, m2.obtenerValor(i, j) + m4.obtenerValor(i, j));
            C.setearValor(i + k, j + k, m1.obtenerValor(i, j) + m3.obtenerValor(i, j) - m2.obtenerValor(i, j) + m6.obtenerValor(i, j));
        }
    }
    return C;
}

public static boolean esPalindromo(int[] u, int ini, int fin) {
    if (ini >= fin) return true;
    if (u[ini] != u[fin]) return false;
    return esPalindromo(u, ini + 1, fin - 1);
}

public static void resolverHanoi(int n, char origen, char auxiliar, char destino) {
    if (n == 1) {
        System.out.println("Mover disco 1 de " + origen + " a " + destino);
        return;
    }
    resolverHanoi(n - 1, origen, destino, auxiliar);
    System.out.println("Mover disco " + n + " de " + origen + " a " + destino);
    resolverHanoi(n - 1, auxiliar, origen, destino);
}

