public class BinarySearch {
    public static int search(int[] sortedArray, int leftIndex, int rightIndex, int targetValue) {
        if (leftIndex > rightIndex) {
            return -1;
        }
        int middleIndex = leftIndex + (rightIndex - leftIndex) / 2;
        if (sortedArray[middleIndex] == targetValue) {
            return middleIndex;
        }
        if (targetValue < sortedArray[middleIndex]) {
            return search(sortedArray, leftIndex, middleIndex - 1, targetValue);
        }
        return search(sortedArray, middleIndex + 1, rightIndex, targetValue);
    }
}

