public class MergeSort {
    public static void sort(int[] elements, int leftIndex, int rightIndex) {
        if (leftIndex >= rightIndex) {
            return;
        }
        int middleIndex = leftIndex + (rightIndex - leftIndex) / 2;
        sort(elements, leftIndex, middleIndex);
        sort(elements, middleIndex + 1, rightIndex);
        mergeHalves(elements, leftIndex, middleIndex, rightIndex);
    }

    private static void mergeHalves(int[] elements, int leftIndex, int middleIndex, int rightIndex) {
        int[] mergedBuffer = new int[rightIndex - leftIndex + 1];
        int leftCursor = leftIndex;
        int rightCursor = middleIndex + 1;
        int writeCursor = 0;

        while (leftCursor <= middleIndex && rightCursor <= rightIndex) {
            if (elements[leftCursor] <= elements[rightCursor]) {
                mergedBuffer[writeCursor++] = elements[leftCursor++];
            } else {
                mergedBuffer[writeCursor++] = elements[rightCursor++];
            }
        }
        while (leftCursor <= middleIndex) {
            mergedBuffer[writeCursor++] = elements[leftCursor++];
        }
        while (rightCursor <= rightIndex) {
            mergedBuffer[writeCursor++] = elements[rightCursor++];
        }
        System.arraycopy(mergedBuffer, 0, elements, leftIndex, mergedBuffer.length);
    }
}

