def merge_sort(elements: list[int]) -> list[int]:
    if len(elements) <= 1:
        return elements
    middle_index = len(elements) // 2
    left_sorted = merge_sort(elements[:middle_index])
    right_sorted = merge_sort(elements[middle_index:])
    return merge_sorted_lists(left_sorted, right_sorted)

def merge_sorted_lists(left_list: list[int], right_list: list[int]) -> list[int]:
    merged_result: list[int] = []
    left_cursor = 0
    right_cursor = 0
    while left_cursor < len(left_list) and right_cursor < len(right_list):
        if left_list[left_cursor] <= right_list[right_cursor]:
            merged_result.append(left_list[left_cursor])
            left_cursor += 1
        else:
            merged_result.append(right_list[right_cursor])
            right_cursor += 1
    merged_result.extend(left_list[left_cursor:])
    merged_result.extend(right_list[right_cursor:])
    return merged_result

