public class QuickSort {
    public static void sort(int[] elements, int lowIndex, int highIndex) {
        if (lowIndex < highIndex) {
            int pivotIndex = partition(elements, lowIndex, highIndex);
            sort(elements, lowIndex, pivotIndex - 1);
            sort(elements, pivotIndex + 1, highIndex);
        }
    }

    private static int partition(int[] elements, int lowIndex, int highIndex) {
        int pivotValue = elements[highIndex];
        int smallerBoundary = lowIndex - 1;
        for (int scanIndex = lowIndex; scanIndex < highIndex; scanIndex++) {
            if (elements[scanIndex] <= pivotValue) {
                smallerBoundary++;
                int temporary = elements[smallerBoundary];
                elements[smallerBoundary] = elements[scanIndex];
                elements[scanIndex] = temporary;
            }
        }
        int temporary = elements[smallerBoundary + 1];
        elements[smallerBoundary + 1] = elements[highIndex];
        elements[highIndex] = temporary;
        return smallerBoundary + 1;
    }
}

