def quick_sort_in_place(elements: list[int], low_index: int, high_index: int) -> None:
    if low_index < high_index:
        pivot_index = partition_segment(elements, low_index, high_index)
        quick_sort_in_place(elements, low_index, pivot_index - 1)
        quick_sort_in_place(elements, pivot_index + 1, high_index)

def partition_segment(elements: list[int], low_index: int, high_index: int) -> int:
    pivot_value = elements[high_index]
    smaller_boundary = low_index - 1
    for scan_index in range(low_index, high_index):
        if elements[scan_index] <= pivot_value:
            smaller_boundary += 1
            elements[smaller_boundary], elements[scan_index] = elements[scan_index], elements[smaller_boundary]
    elements[smaller_boundary + 1], elements[high_index] = elements[high_index], elements[smaller_boundary + 1]
    return smaller_boundary + 1

