import java.util.ArrayList;
import java.util.List;

public class MajorityElementFinder {
    public static int findMajorityElement(int[] elements) {
        Integer candidate = findPseudoMajorityCandidate(elements);
        if (candidate == null) {
            return -1;
        }
        int occurrences = 0;
        for (int value : elements) {
            if (value == candidate) {
                occurrences++;
            }
        }
        return occurrences > elements.length / 2 ? candidate : -1;
    }

    private static Integer findPseudoMajorityCandidate(int[] currentElements) {
        if (currentElements.length == 0) {
            return null;
        }
        if (currentElements.length == 1) {
            return currentElements[0];
        }
        List<Integer> survivors = new ArrayList<>();
        for (int index = 0; index + 1 < currentElements.length; index += 2) {
            if (currentElements[index] == currentElements[index + 1]) {
                survivors.add(currentElements[index]);
            }
        }
        int[] nextLevel = survivors.stream().mapToInt(Integer::intValue).toArray();
        Integer recursiveCandidate = findPseudoMajorityCandidate(nextLevel);
        if (recursiveCandidate != null) {
            return recursiveCandidate;
        }
        if (currentElements.length % 2 == 1) {
            return currentElements[currentElements.length - 1];
        }
        return null;
    }
}

