def find_majority_element(elements: list[int]) -> int:
    candidate = find_pseudo_majority_candidate(elements)
    if candidate is None:
        return -1
    if elements.count(candidate) > len(elements) // 2:
        return candidate
    return -1

def find_pseudo_majority_candidate(current_elements: list[int]) -> int | None:
    if not current_elements:
        return None
    if len(current_elements) == 1:
        return current_elements[0]
    survivors = [
        current_elements[index]
        for index in range(0, len(current_elements) - 1, 2)
        if current_elements[index] == current_elements[index + 1]
    ]
    recursive_candidate = find_pseudo_majority_candidate(survivors)
    if recursive_candidate is not None:
        return recursive_candidate
    if len(current_elements) % 2 == 1:
        return current_elements[-1]
    return None
